final class PaletteBlockDataTests {
    private static byte[] bytes(String s) { return s.getBytes(StandardCharsets.UTF_8); }
    private static String text(byte[] s) { return new String(s,StandardCharsets.UTF_8); }
    private static void check(boolean valid) { if (!valid) throw new AssertionError("Palette block-data contract failed"); }
    private static void rejects(Runnable action) { try { action.run(); } catch (IllegalArgumentException expected) { return; }throw new AssertionError("Expected rejected palette block-data operation"); }
    private static String node(int depth,int last) { return "{\"block\":\"minecraft:water\",\"weight\":2e0,\"data\":{\"a\\u0078is\":\"\\u0079\",\"level\":3e0,\"waterlogged\":false,\"opaque\":{\"seed\":9007199254740993},\"entitySpawn\":\"minecraft:pig\"},\"tileData\":{\"n\":9223372036854775807},\"debug\":false,\"stamp\":"+depth+(depth<last ? ",\"backup\":"+node(depth+1,last) : "")+"}"; }
    private static byte[] fixtureOne(NoiseStyleSourceTests.Case c,String first) { byte[] seed=c.document("{\"style\":\"STATIC\",\"cacheSize\":1e2,\"futureStyle\":9007199254740993}");return NoiseStyleFields.editContainer(seed,c.target(),p -> { byte[] raw=p.enable("palette","[]");var parsed=new LosslessJson(raw);return parsed.objectArrayInsert("palette",0,bytes(first)); },false); }
    private static byte[] fixture(NoiseStyleSourceTests.Case c,String first) { byte[] raw=fixtureOne(c,first);return NoiseStyleFields.editContainer(raw,c.target(),p -> p.objectArrayInsert("palette",1,bytes("{\"block\":\"mod:kept\",\"weight\":999,\"data\":{\"marker\":\"sibling\"},\"sibling\":9007199254740993}")),false); }
    private static LosslessJson at(LosslessJson root,String[] path,int index) { if (index==path.length) return root;String field=path[index];if (index+1<path.length && path[index+1].matches("[0-9]+")) return at(root.objectArray(field).get(Integer.parseInt(path[index+1])),path,index+2);return at(new LosslessJson(bytes(root.token(field))),path,index+1); }
    private static LosslessJson palette(byte[] raw,NoiseStyleSourceTests.Case c) { String path=c.stylePath().substring(0,c.stylePath().length()-".style".length());return at(new LosslessJson(raw),path.split("\\."),0); }
    private static LosslessJson entry(byte[] raw,NoiseStyleSourceTests.Case c,int index) { return palette(raw,c).objectArray("palette").get(index); }
    private static void onlyEntry(byte[] before,byte[] after,NoiseStyleSourceTests.Case c,int index) { String selected=text(entry(before,c,index).sourceBytes()),replacement=text(entry(after,c,index).sourceBytes());String all=text(before);check(all.indexOf(selected)==all.lastIndexOf(selected) && text(after).equals(all.replace(selected,replacement))); }
    static void run(Path temp) throws Exception {
        var cases=NoiseStyleSourceTests.cases().stream().filter(c -> PaletteBlockData.supports(c.target())).toList();check(cases.size()==92);var prefixes=new HashSet<String>();int serial=0;
        check(cases.stream().filter(c -> c.target().proceduralPalette()).count()==52 && cases.stream().filter(c -> c.target().nativeStructurePalette()).count()==8 && cases.stream().filter(c -> c.target().ore()).count()==3);
        for (var c : cases) {
            var context=new PaletteBlockData.Context(c.target(),0);var scope=context.scope();String path=c.path();byte[] original=fixture(c,node(0,8));check(prefixes.add(path+"|"+scope.prefix()) && scope.prefix().startsWith(context.listPrefix()) && !scope.standalone() && scope.depth()==0 && scope.context().equals(context));
            if (!context.fluid() && !c.target().palette()) check(PaletteBlockData.generalTarget(c.target()).styleTarget().equals(c.target()));
            var readonly=PaletteBlockData.readOnlyPaths(entry(original,c,0));check(readonly.containsAll(List.of("data.opaque","data.entitySpawn","tileData","debug","stamp","backup.weight","backup.tileData")) && !readonly.contains("data") && !readonly.contains("backup") && !readonly.contains("weight"));
            for (int depth=0;depth<=8;depth++) {
                int d=depth;var target=new BlockDefinitions.Scope(context,d);check(target.prefix().equals(scope.prefix()+"backup.".repeat(d)));
                check(Arrays.equals(original,BlockDefinitions.setState(path,original,target,"axis","axis",BlockDefinitions.Kind.STRING,"y")) && Arrays.equals(original,BlockDefinitions.setState(path,original,target,"level","level",BlockDefinitions.Kind.NUMBER,"3.000")));
                byte[] changed=BlockDefinitions.setState(path,original,target,"axis","facing",BlockDefinitions.Kind.STRING,"north");onlyEntry(original,changed,c,0);var edited=BlockDefinitions.owner(entry(changed,c,0),d);check(BlockDefinitions.data(edited).token("axis")==null && BlockDefinitions.data(edited).stringToken("facing").equals("north") && edited.token("weight").equals("2e0"));
                byte[] typed=BlockDefinitions.setState(path,original,target,"waterlogged","waterlogged",BlockDefinitions.Kind.NUMBER,"0.5");check(BlockDefinitions.data(BlockDefinitions.owner(entry(typed,c,0),d)).token("waterlogged").equals("0.5"));onlyEntry(original,typed,c,0);
                byte[] removed=BlockDefinitions.removeState(path,original,target,"axis");check(BlockDefinitions.data(BlockDefinitions.owner(entry(removed,c,0),d)).token("axis")==null);onlyEntry(original,removed,c,0);
                byte[] reset=BlockDefinitions.resetData(path,original,target);check(BlockDefinitions.owner(entry(reset,c,0),d).token("data")==null);onlyEntry(original,reset,c,0);byte[] created=BlockDefinitions.createData(path,reset,target);check(BlockDefinitions.data(BlockDefinitions.owner(entry(created,c,0),d)).fields().isEmpty());
                if (d<8) { byte[] noBackup=BlockDefinitions.resetBackup(path,original,target);check(BlockDefinitions.owner(entry(noBackup,c,0),d).token("backup")==null);onlyEntry(original,noBackup,c,0);byte[] seeded=BlockDefinitions.createBackup(path,noBackup,target,target.seedBlock());var child=BlockDefinitions.owner(entry(seeded,c,0),d+1);check(child.fields().equals(Set.of("block")) && child.stringToken("block").equals(target.seedBlock()));onlyEntry(noBackup,seeded,c,0); }
                else rejects(() -> BlockDefinitions.createBackup(path,original,target,target.seedBlock()));
                for (String wrong : List.of("dimensions/a.json","biomes/a.json","regions/a.json","generators/a.json","blocks/a.json","image-maps/a.json")) if (!c.target().resourceBase().equals(ResourceTypes.base(wrong))) rejects(() -> BlockDefinitions.setState(wrong,original,target,"axis","axis",BlockDefinitions.Kind.STRING,"x"));
                rejects(() -> BlockDefinitions.setState("dimensions/nested/a.json",original,target,"axis","axis",BlockDefinitions.Kind.STRING,"x"));
                if (d>0) { byte[] block=BlockDefinitions.setBlock(path,original,target,context.fluid() ? "minecraft:lava" : "some/alias");check(BlockDefinitions.owner(entry(block,c,0),d).stringToken("block").equals(context.fluid() ? "minecraft:lava" : "some/alias"));onlyEntry(original,block,c,0);if (context.fluid()) { rejects(() -> BlockDefinitions.setBlock(path,original,target,"minecraft:stone"));rejects(() -> BlockDefinitions.resetBlock(path,original,target)); }else check(BlockDefinitions.owner(entry(BlockDefinitions.resetBlock(path,original,target),c,0),d).token("block")==null); }
            }
            // Independent palette indices and scalar drafts survive structural changes outside their own scope.
            var sibling=new PaletteBlockData.Context(c.target(),1);byte[] second=BlockDefinitions.setState(path,original,sibling.scope(),"marker","marker",BlockDefinitions.Kind.STRING,"changed");onlyEntry(original,second,c,1);check(Arrays.equals(entry(original,c,0).sourceBytes(),entry(second,c,0).sourceBytes()) && !scope.prefix().equals(sibling.prefix()));
            rejects(() -> BlockDefinitions.setState(path,original,new PaletteBlockData.Context(c.target(),2).scope(),"axis","axis",BlockDefinitions.Kind.STRING,"x"));rejects(() -> new PaletteBlockData.Context(c.target(),-1));rejects(() -> new BlockDefinitions.Scope(context,9));rejects(() -> BlockDefinitions.createBackup(path,original,scope,"mod:new"));
            for (String bad : List.of("null","\"snippet\"","[]","1")) { byte[] invalid=fixture(c,"{\"block\":\"minecraft:water\",\"data\":"+bad+",\"weight\":9007199254740993}");rejects(() -> BlockDefinitions.resetData(path,invalid,scope));check(PaletteBlockData.readOnlyPaths(entry(invalid,c,0)).containsAll(List.of("data","weight")));byte[] keep=BlockDefinitions.createBackup(path,invalid,scope,scope.seedBlock());onlyEntry(invalid,keep,c,0);check(entry(keep,c,0).token("data").equals(bad)); }
            for (String bad : List.of("null","true","[]","\"snippet\"")) { byte[] invalid=fixture(c,"{\"block\":\"minecraft:water\",\"data\":{},\"backup\":"+bad+"}");if (!bad.equals("null")) { rejects(() -> BlockDefinitions.resetBackup(path,invalid,scope));rejects(() -> BlockDefinitions.createBackup(path,invalid,scope,scope.seedBlock())); }byte[] keep=BlockDefinitions.setState(path,invalid,scope,null,"axis",BlockDefinitions.Kind.STRING,"y");check(entry(keep,c,0).token("backup").equals(bad));onlyEntry(invalid,keep,c,0); }
            rejects(() -> BlockDefinitions.createData(path,c.document("{}"),scope));rejects(() -> BlockDefinitions.createData(path,bytes("{}"),scope));
            byte[] absent=fixture(c,"{\"block\":\"minecraft:water\"}");rejects(() -> BlockDefinitions.createData(path,absent,scope.child()));byte[] enabled=BlockDefinitions.createData(path,absent,scope);check(BlockDefinitions.data(entry(enabled,c,0)).fields().isEmpty());onlyEntry(absent,enabled,c,0);
            var drafts=new InspectorDrafts();String inside=scope.prefix()+"data.0",other=sibling.prefix()+"data.0",outside=c.target().draftPrefix()+"zoom";drafts.update(inside,"a","b");drafts.update(other,"a","b");drafts.update(outside,"a","b");check(!drafts.transitionUnder(context.listPrefix(),() -> false,() -> {}) && drafts.count()==3);try { drafts.transitionUnder(context.listPrefix(),() -> true,() -> { throw new IOException("write failed"); });throw new AssertionError(); } catch (IOException expected) { check(drafts.count()==3); }check(drafts.transitionUnder(scope.prefix()+"data.",() -> true,() -> {}) && drafts.contains(other) && drafts.contains(outside));drafts.update(inside,"a","b");check(drafts.transitionUnder(context.listPrefix(),() -> true,() -> {}) && drafts.count()==1 && drafts.contains(outside));
            byte[] changed=BlockDefinitions.setState(path,original,new BlockDefinitions.Scope(context,4),"axis","facing",BlockDefinitions.Kind.STRING,"north");var pack=PackWorkspace.newPack(Map.of(path,original,"objects/opaque.iob",new byte[]{0,1,-1},"effects/opaque.json",bytes("not JSON")));pack.replace(path,changed);String folder="palette-block-data-"+(serial++);pack.save(temp.resolve(folder));pack.exportZip(temp.resolve(folder+".zip"));var saved=PackWorkspace.open(temp.resolve(folder));var imported=PackWorkspace.importZip(temp.resolve(folder+".zip"));for (String key : pack.paths()) check(Arrays.equals(pack.read(key),saved.read(key)) && Arrays.equals(pack.read(key),imported.read(key)));
        }
        // List size/type checks cannot be bypassed through the block-data entry point.
        for (var c : cases) { var scope=new PaletteBlockData.Context(c.target(),0).scope();byte[] raw=fixtureOne(c,"{\"block\":\"minecraft:water\",\"data\":{}}");byte[] oversized=NoiseStyleFields.editContainer(raw,c.target(),p -> { byte[] next=p.sourceBytes();for (int i=1;i<65;i++) next=new LosslessJson(next).objectArrayInsert("palette",i,bytes("{}"));return next; },false);rejects(() -> BlockDefinitions.setState(c.path(),oversized,scope,null,"axis",BlockDefinitions.Kind.STRING,"y"));for (String bad : List.of("null","{}","\"snippet\"","[null]","[1]")) { byte[] invalid=replaceList(raw,c,bad);rejects(() -> BlockDefinitions.createData(c.path(),invalid,scope)); } }
        for (var c : NoiseStyleSourceTests.cases()) if (!PaletteBlockData.supports(c.target())) rejects(() -> new PaletteBlockData.Context(c.target(),0));for (var c : cases) rejects(() -> new PaletteBlockData.Context(c.target().child(),0));rejects(() -> new PaletteBlockData.Context(null,0));rejects(() -> BlockDefinitions.setBlock("blocks/a.json",bytes("{}"),(BlockDefinitions.Scope)null,"stone"));
        System.out.println("PASS: inline block states/backups across 92 registered material palette contexts and eight backup levels, strict owner/index/list/depth/type guards, fluid-role restrictions, precise read-only descendants, exact root-block/weight/style/sibling preservation, independent and parent-scoped drafts, and byte-exact Save/ZIP without registry lookup, palette sampling or generation");
    }
    private static byte[] replaceList(byte[] raw,NoiseStyleSourceTests.Case c,String next) { String previous=palette(raw,c).token("palette");String all=text(raw);check(all.indexOf(previous)==all.lastIndexOf(previous));return bytes(all.replace(previous,next)); }
}
